SELECT UTC_TIMESTAMP() observed_utc; SELECT a.id,a.deleted_at IS NOT NULL deleted,s.account_state,s.login_state,s.desired_login_state,s.state_source FROM account a JOIN account_state s ON s.account_id=a.id AND s.tenant_id=a.tenant_id WHERE a.tenant_id=1 AND a.id IN (1038,1736); SELECT COUNT(*) new_online_commands FROM protocol_command_outbox WHERE tenant_id=1 AND aggregate_id IN (1038,1736) AND command_type='account.online.requested' AND created_at>=1791294575617; SELECT COUNT(*) new_proxy_failures FROM account_online_attempt_log WHERE tenant_id=1 AND account_id IN (1038,1736) AND diagnosis_code='PROXY_FAILED' AND occurred_at>='2026-10-06 13:49:35.617000'; SELECT status,COUNT(*) n FROM ip_proxy WHERE tenant_id=1 AND deleted_at IS NULL GROUP BY status; SELECT status,last_check_error,COUNT(*) n FROM ip_proxy WHERE tenant_id=1 AND deleted_at IS NULL AND status=3 GROUP BY 1,2;